// Reads the tool list the site's search uses (assets/search-index.js, generated by scripts/generate.py).
const fs = require('fs');
const path = require('path');

const source = fs.readFileSync(path.join(__dirname, '..', 'assets', 'search-index.js'), 'utf8');
const TOOLS = JSON.parse(source.slice(source.indexOf('['), source.lastIndexOf(']') + 1));

// Sections whose tools must each offer an Example button (same rule as scripts/generate.py).
const CRYPTO_SECTIONS = ['crypto', 'bitcoin', 'evm', 'solana', 'ton', 'cardano', 'sui', 'cosmos', 'polkadot'];

module.exports = {
  TOOLS,
  readyTools: TOOLS.filter(t => t.ready),
  cryptoTools: TOOLS.filter(t => t.ready && CRYPTO_SECTIONS.includes(t.url.split('/')[0])),
};
